// Match the complete standard-cell placement, independent of stream order and
// GDS timestamps. The sidecar is generated by scripts/strata-parser/design02_pe.py.
export async function assignProcessingElements(templates, names) {
  const rows = [];
  for (const [id, t] of templates) {
    const name = names[id];
    if (!name.startsWith("sky130_fd_sc_hd__")) continue;
    for (let i = 0; i < t.placements.length; i += 8) {
      const [a, b, c, d, x, y] = t.placements.slice(i, i + 6);
      if ([a, b, c, d].some((n) => Math.abs(n - Math.round(n)) > 1e-8)) return false;
      rows.push({ key: [name, Math.round(x * 1000), Math.round(y * 1000), ...[a, b, c, d].map(Math.round)].join(","), t, index: i / 8 });
    }
  }
  if (!rows.length || !globalThis.crypto?.subtle) return false;
  rows.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  const bytes = new TextEncoder().encode(rows.map((r) => r.key).join("\n"));
  const digest = Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256", bytes)), (n) => n.toString(16).padStart(2, "0")).join("");
  const response = await fetch(new URL("./assets/design02-pe.json", import.meta.url));
  if (!response.ok) return false;
  const owners = (await response.json())[digest];
  if (owners?.length !== rows.length) return false;
  for (const [i, { t, index }] of rows.entries()) {
    t.pe ??= new Uint8Array(t.placements.length / 8);
    t.pe[index] = Number(owners[i]);
  }
  return true;
}
